"\nScanning the drive for archives:\n\n"
"ERROR: errno=2 : No such file or directory\n"
"%s\n\n\nSystem ERROR:\n"
"errno=2 : No such file or directory\n";

const char *cmdline_error_no_archive =
"\n\nCommand Line Error:\n"
"Cannot find archive name\n";

