"\nCommand Line Error:\n"
"Unknown switch:\n"
"%s\n";

int main(int argc, char **argv) {
    int printed_header = 0;
    if (argc == 1) {
        printf("%s%s", header, help);
        return 0;
    }
    // handle help flags
    if (strcmp(argv[1], "--help") == 0 || strcmp(argv[1], "-h") == 0) {
        printf("%s%s", header, help);
        return 0;
    }
    // unknown long switch (e.g., --version) -> error
    if (strncmp(argv[1], "--", 2) == 0) {
        printf("%s", unknown_switch_fmt);
        printf(argv[1]); // print the switch
        printf("\n");
        return 0;
