            // no archive name
            printf("%s", cmdline_error_no_archive);
            return 0;
        }
        // simulate scanning and missing file
        printf(list_no_file, argv[2]);
        return 0;
    }
    if (strcmp(argv[1], "a") == 0) {
        // requires archive name
