cat > compile.sh <<'EOF'
#!/bin/sh
set -e
gcc -O2 -o executable main.c
EOF

chmod +x compile.sh

# create .gitignore
cat > .gitignore <<'EOF'
/executable
EOF

# add files to git
git add main.c compile.sh .gitignore
git commit -m "Implement minimal 7za-like CLI output" || true

# run compile to produce executable
./compile.sh

# test some commands
./executable --help | sed -n '1,40p' > /tmp/check1
./executable i | sed -n '1,40p' > /tmp/check2
./executable l nofile.7z > /tmp/check3 || true
./executable a > /tmp/check4 || true

echo '--- help ---'
sed -n '1,40p' /tmp/check1
echo '--- info ---'
sed -n '1,40p' /tmp/check2
echo '--- list ---'
sed -n '1,80p' /tmp/check3
echo '--- add ---'
sed -n '1,40p' /tmp/check4
"}

